#!/bin/bash
#******************************************************************************
# l4t_verify_packages.sh - Verify Debian packages generated by l4t_gen_delivery_package.sh
#
# Usage:
#   ./l4t_verify_packages.sh [-v <version>] [-V <vendor>] [-s <som>] [-c <carrier-board>] [--verbose]
#
# This script verifies that the installation directory used for Debian package
# generation contains all expected files.
#
# Options:
#   -v, --l4t-version VERSION   Version filter (supports wildcards: 36.*, 35.6.*)
#   -V, --vendor VENDOR         Vendor filter: generic, forecr (default: all)
#   -s, --som SOM               SoM filter: t210, t186 (32.x only, default: all)
#   -c, --carrier-board BOARD   Carrier board filter (default: all for vendor)
#   --verbose                   Show detailed file paths
#   --list                      List matching configurations and exit
#   -h, --help                  Show this help message
#
# Examples:
#   ./l4t_verify_packages.sh                        # Verify all packages
#   ./l4t_verify_packages.sh -v 36.4.3              # Verify 36.4.3 all vendors
#   ./l4t_verify_packages.sh -v 36.4.3 -V forecr    # Verify 36.4.3 forecr only
#   ./l4t_verify_packages.sh -v 32.7.1 -s t186      # Verify 32.7.1 t186 SoM
#   ./l4t_verify_packages.sh -v "36.*" --verbose    # Verify all 36.x with details
#******************************************************************************

set -e

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

# Source unified environment (provides enumeration functions)
. "$SCRIPT_DIR/l4t_environment.sh"

#******************************************************************************
# Default values
#******************************************************************************
VERSION_FILTER=""
VENDOR_FILTER=""
SOM_FILTER=""
CARRIER_FILTER=""
VERBOSE=0
LIST_ONLY=0

#******************************************************************************
# Colors
#******************************************************************************
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
CYAN='\033[0;36m'
NC='\033[0m'

#******************************************************************************
# Help function
#******************************************************************************
show_help() {
    head -24 "$0" | tail -n +2 | sed 's/^#//' | sed 's/^\*//g'
    echo ""
    local all_versions=$(get_all_versions)
    echo "Available versions: $all_versions"
    echo ""
    echo "Version-vendor support:"
    for v in $all_versions; do
        local vendors=$(get_vendors_for_version "$v")
        echo "  $v: $vendors"
    done
}

#******************************************************************************
# Parse arguments
#******************************************************************************
while [[ $# -gt 0 ]]; do
    case "$1" in
        -v|--l4t-version)
            VERSION_FILTER="$2"
            shift 2
            ;;
        -V|--vendor)
            VENDOR_FILTER="$2"
            shift 2
            ;;
        -s|--som)
            SOM_FILTER="$2"
            shift 2
            ;;
        -c|--carrier-board)
            CARRIER_FILTER="$2"
            shift 2
            ;;
        --verbose)
            VERBOSE=1
            shift
            ;;
        --list)
            LIST_ONLY=1
            shift
            ;;
        -h|--help)
            show_help
            exit 0
            ;;
        *)
            echo "Error: Unknown argument: $1"
            echo "Use --help for usage information."
            exit 1
            ;;
    esac
done

#******************************************************************************
# Validate filters
#******************************************************************************
if ! validate_filters "$VERSION_FILTER" "$VENDOR_FILTER" "$SOM_FILTER" "$CARRIER_FILTER"; then
    exit 1
fi

#******************************************************************************
# Get configurations to process
#******************************************************************************
configs=$(enumerate_configs "$VERSION_FILTER" "$VENDOR_FILTER" "$SOM_FILTER" "$CARRIER_FILTER")
config_count=$(echo "$configs" | wc -l)

#******************************************************************************
# List mode
#******************************************************************************
if [[ $LIST_ONLY -eq 1 ]]; then
    echo "Matching configurations ($config_count):"
    echo ""
    printf "%-12s %-12s %-8s %-15s\n" "VERSION" "VENDOR" "SOM" "CARRIER"
    echo "-------------------------------------------------------"
    for config in $configs; do
        parse_config "$config"
        printf "%-12s %-12s %-8s %-15s\n" "$CFG_VERSION" "$CFG_VENDOR" "${CFG_SOM:--}" "$CFG_CARRIER"
    done
    exit 0
fi

#******************************************************************************
# Counters
#******************************************************************************
TOTAL_ERRORS=0
TOTAL_WARNINGS=0
TOTAL_CHECKS=0
TOTAL_PASSED=0
TOTAL_FAILED=0
TOTAL_SKIPPED=0

#******************************************************************************
# Helper functions
#******************************************************************************
# Reset per-package counters
reset_counters() {
    PKG_ERRORS=0
    PKG_WARNINGS=0
    PKG_CHECKS=0
}

# Extract expected EG DTBO files from Makefiles
# Args: version, vendor_source_dir (empty for generic)
# Returns: list of expected dtbo filenames (one per line)
get_expected_eg_dtbo() {
    local version="$1"
    local vendor_source_dir="$2"

    local source_base="$SCRIPT_DIR/sources/$version"
    local makefiles=""

    # Determine which source directory to use
    if [[ -n "$vendor_source_dir" ]]; then
        source_base="$source_base/$vendor_source_dir"
    else
        source_base="$source_base/Linux_for_Tegra"
    fi

    # Find all Makefiles containing dtbo-y and eg patterns
    if [[ -d "$source_base" ]]; then
        makefiles=$(find "$source_base" -name "Makefile" -type f -exec grep -l "dtbo.*eg" {} \; 2>/dev/null)
    fi

    # Extract dtbo-y lines containing -eg- patterns
    for makefile in $makefiles; do
        grep -E 'dtbo-.*\+=' "$makefile" 2>/dev/null | \
            grep -E '\-eg\-' | \
            sed -E 's/.*\+= *([^ ]+\.dtbo).*/\1/' | \
            sort -u
    done | sort -u
}

check_file() {
    local file="$1"
    local description="$2"
    local required="${3:-1}"  # 1=required, 0=optional

    PKG_CHECKS=$((PKG_CHECKS + 1))

    if [[ -f "$file" ]]; then
        if [[ $VERBOSE -eq 1 ]]; then
            echo -e "  ${GREEN}[OK]${NC} $description"
            echo "       $file"
        fi
        return 0
    else
        if [[ $required -eq 1 ]]; then
            echo -e "  ${RED}[MISSING]${NC} $description"
            if [[ $VERBOSE -eq 1 ]]; then
                echo "       Expected: $file"
            fi
            PKG_ERRORS=$((PKG_ERRORS + 1))
        else
            if [[ $VERBOSE -eq 1 ]]; then
                echo -e "  ${YELLOW}[OPTIONAL]${NC} $description (not found)"
            fi
            PKG_WARNINGS=$((PKG_WARNINGS + 1))
        fi
        return 1
    fi
}

check_dir() {
    local dir="$1"
    local description="$2"
    local required="${3:-1}"

    PKG_CHECKS=$((PKG_CHECKS + 1))

    if [[ -d "$dir" ]]; then
        if [[ $VERBOSE -eq 1 ]]; then
            local count=$(find "$dir" -type f 2>/dev/null | wc -l)
            echo -e "  ${GREEN}[OK]${NC} $description ($count files)"
            echo "       $dir"
        fi
        return 0
    else
        if [[ $required -eq 1 ]]; then
            echo -e "  ${RED}[MISSING]${NC} $description"
            if [[ $VERBOSE -eq 1 ]]; then
                echo "       Expected: $dir"
            fi
            PKG_ERRORS=$((PKG_ERRORS + 1))
        else
            if [[ $VERBOSE -eq 1 ]]; then
                echo -e "  ${YELLOW}[OPTIONAL]${NC} $description (not found)"
            fi
            PKG_WARNINGS=$((PKG_WARNINGS + 1))
        fi
        return 1
    fi
}

check_files_exist() {
    local dir="$1"
    local pattern="$2"
    local description="$3"
    local required="${4:-1}"

    PKG_CHECKS=$((PKG_CHECKS + 1))

    local files=$(find "$dir" -name "$pattern" -type f 2>/dev/null)
    local count=0
    if [[ -n "$files" ]]; then
        count=$(echo "$files" | wc -l)
    fi

    if [[ $count -gt 0 ]]; then
        if [[ $VERBOSE -eq 1 ]]; then
            echo -e "  ${GREEN}[OK]${NC} $description ($count files matching '$pattern')"
            echo "$files" | head -5 | sed 's/^/       /'
            if [[ $count -gt 5 ]]; then
                echo "       ... and $((count - 5)) more"
            fi
        fi
        return 0
    else
        if [[ $required -eq 1 ]]; then
            echo -e "  ${RED}[MISSING]${NC} $description (no files matching '$pattern')"
            PKG_ERRORS=$((PKG_ERRORS + 1))
        else
            if [[ $VERBOSE -eq 1 ]]; then
                echo -e "  ${YELLOW}[OPTIONAL]${NC} $description (no files matching '$pattern')"
            fi
            PKG_WARNINGS=$((PKG_WARNINGS + 1))
        fi
        return 1
    fi
}

