#******************************************************************************
# Verify a single package
#******************************************************************************
verify_package() {
    local version="$1"
    local vendor="$2"
    local som="$3"
    local carrier="$4"

    reset_counters

    # Compute derived variables for this configuration
    local version_major=$(echo $version | awk -F '.' '{print $1}')

    # JetPack version infix
    local jetpack=$($_EGCFG "version.$version.jetpack" "$L4T_CONFIG_FILE" 2>/dev/null || echo "")
    local jp_infix=""
    [[ -n "$jetpack" ]] && jp_infix="-jp${jetpack}"

    # Directory naming based on vendor/SoM/carrier-board
    local linux_for_tegra_dir
    local vendor_source_dir=""
    local som_source_dir=""
    if [[ "$vendor" == "generic" ]]; then
        if [[ -n "$som" ]]; then
            local som_suffix=$(get_som_dir_suffix "$som")
            linux_for_tegra_dir=Linux_for_Tegra_${som_suffix}
            som_source_dir=Linux_for_Tegra_${som_suffix}
        else
            linux_for_tegra_dir=Linux_for_Tegra
        fi
    else
        local carrier_suffix=$(get_carrier_dir_suffix "$carrier")
        if [[ -n "$carrier_suffix" ]]; then
            linux_for_tegra_dir=Linux_for_Tegra_${vendor}_${carrier_suffix}
        else
            linux_for_tegra_dir=Linux_for_Tegra_${vendor}
        fi
        vendor_source_dir=Linux_for_Tegra_${vendor}
    fi

    local jetson_dir="$SCRIPT_DIR/$version"
    local rootfs_dir="$jetson_dir/${linux_for_tegra_dir}/rootfs"

    # Package naming (mirrors l4t_gen_delivery_package.sh)
    local package_name
    if [[ "$vendor" == "generic" ]]; then
        if [[ -n "$som" ]]; then
            package_name=jetson-l4t-${version}${jp_infix}-${som}-eg-cams
        else
            package_name=jetson-l4t-${version}${jp_infix}-eg-cams
        fi
    else
        local carrier_deb=$(echo "$carrier" | tr '_' '-')
        package_name=jetson-l4t-${version}${jp_infix}-${vendor}-${carrier_deb}-eg-cams
    fi

    local package_dir="$jetson_dir/$package_name"

    # Check if package directory exists
    if [[ ! -d "$package_dir" ]]; then
        echo -e "  ${YELLOW}[SKIPPED]${NC} $package_name - package directory not found"
        TOTAL_SKIPPED=$((TOTAL_SKIPPED + 1))
        return 2
    fi

    # Auto-detect standalone build
    local standalone_build=0
    local kernel_version
    local eg_kernel_version=$(ls "$rootfs_dir/lib/modules/" 2>/dev/null | grep -- '-eg$')
    if [[ -n "$eg_kernel_version" ]]; then
        standalone_build=1
        kernel_version="$eg_kernel_version"
    else
        kernel_version=$(ls "$rootfs_dir/lib/modules/" 2>/dev/null | grep -v -- '-eg$' | head -1)
    fi

    if [[ $VERBOSE -eq 1 ]]; then
        echo ""
        echo "  Version: $version (JetPack ${jetpack:-unknown})"
        echo "  Vendor: $vendor"
        [[ -n "$som" ]] && echo "  SoM: $som"
        echo "  Carrier board: $carrier"
        echo "  Kernel version: ${kernel_version:-unknown}"
        if [[ $standalone_build -eq 1 ]]; then
            echo "  Mode: standalone"
        else
            echo "  Mode: standard"
        fi
        echo ""
    fi

    # 1. Verify boot files
    if [[ $VERBOSE -eq 1 ]]; then
        echo "  --- Boot files ---"
    fi

    check_dir "$package_dir/boot/eg" "Boot EG directory"

    if [[ -d "$package_dir/boot/eg" ]]; then
        if [[ $standalone_build -eq 1 ]]; then
            check_file "$package_dir/boot/eg/Image" "Standalone kernel Image"
            check_file "$package_dir/boot/eg/initrd-eg" "Standalone initramfs"
        fi
    fi

    # Verify each expected DTBO file from Makefile
    # For SoM builds, look in the SoM-specific source dir; for vendor builds, use vendor dir
    local dtbo_source_dir="${som_source_dir:-$vendor_source_dir}"
    local expected_dtbo=$(get_expected_eg_dtbo "$version" "$dtbo_source_dir")
    local dtbo_count=0
    local dtbo_missing=0

    if [[ -n "$expected_dtbo" ]]; then
        while IFS= read -r dtbo_file; do
            dtbo_count=$((dtbo_count + 1))
            if [[ -f "$package_dir/boot/$dtbo_file" ]]; then
                if [[ $VERBOSE -eq 1 ]]; then
                    echo -e "  ${GREEN}[OK]${NC} $dtbo_file"
                fi
            else
                echo -e "  ${RED}[MISSING]${NC} $dtbo_file"
                dtbo_missing=$((dtbo_missing + 1))
                PKG_ERRORS=$((PKG_ERRORS + 1))
            fi
            PKG_CHECKS=$((PKG_CHECKS + 1))
        done <<< "$expected_dtbo"

        if [[ $dtbo_missing -eq 0 ]]; then
            if [[ $VERBOSE -eq 0 ]]; then
                echo -e "  ${GREEN}[OK]${NC} All $dtbo_count EG device tree overlays present"
            fi
        else
            echo -e "  ${RED}[ERROR]${NC} $dtbo_missing/$dtbo_count EG device tree overlays missing"
        fi
    else
        # Fallback: check if any EG dtbo files exist
        check_files_exist "$package_dir/boot" "*-eg-*.dtb*" "EG device tree overlays"
    fi

    # 2. Verify etc files
    if [[ $VERBOSE -eq 1 ]]; then
        echo "  --- Configuration files ---"
    fi

    check_file "$package_dir/etc/version_eg_cams" "Version info file"

    # 3. Verify kernel modules
    if [[ $VERBOSE -eq 1 ]]; then
        echo "  --- Kernel modules ---"
    fi

    local modules_dir="$package_dir/lib/modules"

    # Auto-detect EG kernel modules from sources (source-based detection).
    # Cross-references Exosens .c sources with the i2c Makefile to find EG modules.
    local eg_modules=""
    if [[ $standalone_build -eq 0 ]]; then
        # EG module list is always derived from the version-generic Makefile.
        # SoM/vendor layers contain NVIDIA stock Makefiles (no EG modules).
        local i2c_makefile=""
        for rel in "source/public/kernel/nvidia/drivers/media/i2c/Makefile" \
                   "source/nvidia-oot/drivers/media/i2c/Makefile"; do
            local candidate="$SCRIPT_DIR/sources/$version/Linux_for_Tegra/$rel"
            [[ -f "$candidate" ]] && i2c_makefile="$candidate"
        done
        if [[ -n "$i2c_makefile" ]]; then
            local eg_srcs=()
            while IFS= read -r f; do
                eg_srcs+=("$(basename "$f" .c)")
            done < <(find "$SCRIPT_DIR/sources" -path "*/drivers/media/i2c/*.c" 2>/dev/null)

            local makefile_joined
            makefile_joined=$(awk '{if(/\\$/) {printf "%s ", substr($0,1,length($0)-1)} else {print}}' "$i2c_makefile")

            declare -A _mod_srcs_v
            while IFS= read -r line; do
                line="${line%%#*}"
                if [[ "$line" =~ ^([a-zA-Z0-9_-]+)-[yo][^[:space:]=]*[[:space:]]*([:+]?=)[[:space:]]*(.*) ]]; then
                    local _m="${BASH_REMATCH[1]}"
                    for tok in ${BASH_REMATCH[3]}; do
                        [[ "$tok" == *.o ]] && _mod_srcs_v["$_m"]+=" $(basename "${tok%.o}")"
                    done
                fi
            done <<< "$makefile_joined"

            while IFS= read -r line; do
                line="${line%%#*}"
                if [[ "$line" =~ ^obj-[^+]*\+=[[:space:]]*([a-zA-Z0-9_-]+)\.o ]]; then
                    local _mod="${BASH_REMATCH[1]}"
                    local _srcs="${_mod_srcs_v[$_mod]:-$_mod}"
                    for _src in $_srcs; do
                        for _eg in "${eg_srcs[@]}"; do
                            if [[ "$_src" == "$_eg" ]]; then
                                eg_modules+="${_mod}"$'\n'
                                break 2
                            fi
                        done
                    done
                fi
            done <<< "$makefile_joined"
            unset _mod_srcs_v
            eg_modules=$(echo "$eg_modules" | sort -u)
        fi
    fi

    if [[ $standalone_build -eq 1 ]]; then
        check_dir "$modules_dir/$kernel_version" "Kernel modules directory"
        if [[ -d "$modules_dir/$kernel_version" ]]; then
            check_files_exist "$modules_dir/$kernel_version" "*.ko" "Kernel modules"
        fi
    else
        if [[ $version_major -ge 36 ]]; then
            local i2c_dir="$modules_dir/$kernel_version/updates/drivers/media/i2c"
            if [[ -n "$eg_modules" ]]; then
                while IFS= read -r mod_name; do
                    [[ -z "$mod_name" ]] && continue
                    check_file "$i2c_dir/${mod_name}.ko" "Exosens module ${mod_name}"
                done <<< "$eg_modules"
            fi
            check_file "$modules_dir/$kernel_version/updates/drivers/video/tegra/camera/tegra_camera_platform.ko" "Tegra camera platform module" 0
            check_file "$modules_dir/$kernel_version/updates/drivers/media/platform/tegra/camera/tegra-camera.ko" "Tegra camera module" 0
            check_file "$modules_dir/$kernel_version/updates/drivers/video/tegra/host/nvcsi/nvhost-nvcsi-t194.ko" "NVCSI module" 0
        else
            local i2c_dir="$modules_dir/$kernel_version/kernel/drivers/media/i2c"
            if [[ -n "$eg_modules" ]]; then
                while IFS= read -r mod_name; do
                    [[ -z "$mod_name" ]] && continue
                    check_file "$i2c_dir/${mod_name}.ko" "Exosens module ${mod_name}"
                done <<< "$eg_modules"
            fi
        fi
    fi

    # 4. Verify source files
    if [[ $VERBOSE -eq 1 ]]; then
        echo "  --- Source files ---"
    fi

    check_dir "$package_dir/usr" "User binaries directory"
    if [[ -d "$package_dir/usr/bin" ]]; then
        check_file "$package_dir/usr/bin/eg_dt_camera_config_set.sh" "Camera config set script"
        check_file "$package_dir/usr/bin/eg_dt_camera_config_get.sh" "Camera config get script"
        check_file "$package_dir/usr/bin/detect_jetson_board.sh" "Jetson board detection script"
    fi

    check_dir "$package_dir/opt/eg" "EG configuration directory"
    if [[ -d "$package_dir/opt/eg" ]]; then
        check_dir "$package_dir/opt/eg/jetson-io" "Jetson-IO configuration"
        check_dir "$package_dir/opt/eg/doc" "Documentation" 0
    fi

    # Update totals
    TOTAL_CHECKS=$((TOTAL_CHECKS + PKG_CHECKS))
    TOTAL_ERRORS=$((TOTAL_ERRORS + PKG_ERRORS))
    TOTAL_WARNINGS=$((TOTAL_WARNINGS + PKG_WARNINGS))

    # Return result
    if [[ $PKG_ERRORS -eq 0 ]]; then
        TOTAL_PASSED=$((TOTAL_PASSED + 1))
        return 0
    else
        TOTAL_FAILED=$((TOTAL_FAILED + 1))
        return 1
    fi
}

#******************************************************************************
# Main execution
#******************************************************************************
echo "============================================"
echo -e "${CYAN}L4T Package Verification${NC}"
echo "============================================"
echo ""
echo "Configurations to verify: $config_count"
if [[ $VERBOSE -eq 1 ]]; then
    echo "Mode: verbose"
fi
echo ""

config_index=0
for config in $configs; do
    config_index=$((config_index + 1))
    parse_config "$config"

    som_label="${CFG_SOM:+/$CFG_SOM}"
    echo -n -e "[$config_index/$config_count] ${CYAN}$CFG_VERSION${NC} / $CFG_VENDOR${som_label} / $CFG_CARRIER: "

    if verify_package "$CFG_VERSION" "$CFG_VENDOR" "$CFG_SOM" "$CFG_CARRIER"; then
        echo -e "${GREEN}PASSED${NC} ($PKG_CHECKS checks)"
    elif [[ $? -eq 2 ]]; then
        # Skipped (message already printed by verify_package)
        :
    else
        echo -e "${RED}FAILED${NC} ($PKG_ERRORS errors, $PKG_WARNINGS warnings)"
    fi
done

#******************************************************************************
# Summary
#******************************************************************************
echo ""
echo "============================================"
echo -e "${CYAN}SUMMARY${NC}"
echo "============================================"
echo ""
echo "Total configurations: $config_count"
echo -e "  ${GREEN}Passed: $TOTAL_PASSED${NC}"
echo -e "  ${RED}Failed: $TOTAL_FAILED${NC}"
echo -e "  ${YELLOW}Skipped: $TOTAL_SKIPPED${NC}"
echo ""
echo "Total checks: $TOTAL_CHECKS"
echo -e "Total errors: $([ $TOTAL_ERRORS -eq 0 ] && echo -e "${GREEN}$TOTAL_ERRORS${NC}" || echo -e "${RED}$TOTAL_ERRORS${NC}")"
echo -e "Total warnings: $([ $TOTAL_WARNINGS -eq 0 ] && echo -e "${GREEN}$TOTAL_WARNINGS${NC}" || echo -e "${YELLOW}$TOTAL_WARNINGS${NC}")"
echo ""

if [[ $TOTAL_FAILED -eq 0 && $TOTAL_PASSED -gt 0 ]]; then
    echo -e "${GREEN}All packages verified successfully${NC}"
    exit 0
elif [[ $TOTAL_PASSED -eq 0 && $TOTAL_SKIPPED -eq $config_count ]]; then
    echo -e "${YELLOW}No packages found to verify${NC}"
    exit 0
else
    echo -e "${RED}Some packages failed verification${NC}"
    exit 1
fi
